package com.aistock.market.comparison;
import com.aistock.market.marketlifecycle.*;import com.aistock.common.marketlifecycle.*;import com.aistock.market.support.MarketDatabaseFixture;import com.aistock.market.version.MarketVersionRepository;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static com.aistock.market.comparison.ComparisonUpdateSamples.*;
@Tag("mysql") class ComparisonLocalUseMysqlTest {
 static class Setup {final MarketDatabaseFixture db=new MarketDatabaseFixture();final MutableClock clock=new MutableClock(NOW.instant());final ObjectMapper json=new ObjectMapper().findAndRegisterModules();final MarketVersionRepository market=new MarketVersionRepository(db.jdbc());final UUID raw=raw(db,"old",START,END,"10",false,0,clock);final ComparisonUpdateRecords.Request request=request(db,raw,START,END,clock);final ComparisonRefreshRepository repo=new ComparisonRefreshRepository(db.jdbc(),new ComparisonEvidenceRepository(market,json,clock),new ComparisonEvidenceValidator(clock),json,clock);final MarketLifecycleService lifecycle=new MarketLifecycleService(db.jdbc(),clock,()->true);final MarketEvidenceGate gate=new MarketEvidenceGate(lifecycle,true);final MarketComparisonUseOwner uses=new MarketComparisonUseOwner(db.jdbc(),json,repo,lifecycle,gate,clock,true);final ComparisonUpdateQuery query=spy(new ComparisonUpdateQuery(market,validCalendar(END.minusDays(10),END,clock),clock));final AtomicInteger calls=new AtomicInteger();ComparisonRefreshService service(){return new ComparisonRefreshService(repo,query,r->{calls.incrementAndGet();assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return new ComparisonCollector.Collected("AVAILABLE",candidate(r,"10","20",clock),null);},clock,uses);}void replaceHead(){raw(db,"new",START,END,"11",false,1,clock);}MarketLifecycleRecords.Receipt disable(){var v=lifecycle.snapshot("SH600030",raw.toString());return lifecycle.action("SH600030",raw.toString(),UUID.randomUUID().toString(),new MarketUseRecords.Command(UUID.randomUUID().toString(),"DISABLE",v.revision(),"test disable"));}}
 @Test void serviceAdmitsBeforeReadingOriginalRawAndReleasesOnlyAfterPublication(){var s=new Setup();doAnswer(c->{assertEquals(1,s.db.jdbc().queryForObject("select count(*) from comparison_refresh_receipt",Integer.class));assertEquals(1,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());return c.callRealMethod();}).when(s.query).fixedWindow(any());var done=s.service().refresh(s.request);assertEquals("AVAILABLE",done.state());assertEquals(1,s.calls.get());assertEquals(0,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());var p=s.uses.proof(s.request.operationId(),"1");assertEquals("SUCCEEDED",p.path("state").asText());assertEquals(done.versionId(),p.path("resultIdentity").asText());assertEquals(9,p.size());assertEquals(done,s.service().refresh(s.request));assertEquals(1,s.calls.get());assertEquals(1,s.db.jdbc().queryForObject("select count(*) from market_local_comparison_use",Integer.class));}
 @Test void blockedFrozenRawNeverReadsWindowOrCollects(){var s=new Setup();s.replaceHead();s.disable();var result=s.service().refresh(s.request);assertEquals("FAILED",result.state());assertEquals("MARKET_VERSION_USE_BLOCKED",result.errorCode());verify(s.query,never()).fixedWindow(any());assertEquals(0,s.calls.get());assertEquals(0,s.db.jdbc().queryForObject("select count(*) from comparison_evidence_version",Integer.class));}
 @Test void inflightDisableWaitsAndOriginalAllowedExecutionCanFinish(){var s=new Setup();s.replaceHead();var service=new ComparisonRefreshService(s.repo,s.query,r->{assertEquals("DRAINING",s.disable().afterState());assertEquals(1,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());return new ComparisonCollector.Collected("AVAILABLE",candidate(r,"10","20",s.clock),null);},s.clock,s.uses);assertEquals("AVAILABLE",service.refresh(s.request).state());assertEquals("DISABLED",s.lifecycle.snapshot("SH600030",s.raw.toString()).useState());assertEquals(0,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());}
 @Test void expiredProofPhysicallyFencesLatePublisherEvenOnClockRollback(){var s=new Setup();s.repo.begin(s.request);try(var scope=s.uses.acquire(s.request)){}assertThrows(RuntimeException.class,()->s.uses.proof(s.request.operationId(),"1"));s.clock.advance(Duration.ofSeconds(91));var p=s.uses.proof(s.request.operationId(),"1");assertEquals("FAILED",p.path("state").asText());assertEquals("FAILED",s.db.jdbc().queryForObject("select state from comparison_refresh_receipt",String.class));s.clock.advance(Duration.ofSeconds(-90));assertEquals("FAILED",s.repo.complete(s.request,candidate(s.request,"10","20",s.clock),null).state());assertEquals(p,s.uses.proof(s.request.operationId(),"1"));assertEquals(0,s.db.jdbc().queryForObject("select count(*) from comparison_evidence_version",Integer.class));}
 @Test void unknownLocalRegistrationRecoversOriginalIdWithoutRecollectOrReregister(){var s=new Setup();var spy=spy(s.lifecycle);doAnswer(c->{c.callRealMethod();throw MarketComparisonUseOwner.unavailable();}).when(spy).register(anyString(),any(),any(),eq(true));var uses=new MarketComparisonUseOwner(s.db.jdbc(),s.json,s.repo,spy,new MarketEvidenceGate(spy,true),s.clock,true);var service=new ComparisonRefreshService(s.repo,s.query,r->{s.calls.incrementAndGet();throw new AssertionError("no collect after unknown grant");},s.clock,uses);assertEquals("FAILED",service.refresh(s.request).state());assertEquals(1,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());var original=s.db.jdbc().queryForObject("select request_id from market_local_comparison_use",String.class);var restarted=new MarketComparisonUseOwner(s.db.jdbc(),s.json,s.repo,s.lifecycle,s.gate,s.clock,true);restarted.recoverOne(s.request.operationId());assertEquals(0,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());assertTrue(s.db.jdbc().queryForObject("select completion_acked from market_local_comparison_use",Boolean.class));assertEquals(original,s.db.jdbc().queryForObject("select request_id from market_version_use_request",String.class));verify(spy,times(1)).register(anyString(),any(),any(),anyBoolean());assertEquals(0,s.calls.get());}
 @Test void proofClockIsReadAfterRealOperationRowLockWait()throws Exception{var s=new Setup();s.repo.begin(s.request);try(var scope=s.uses.acquire(s.request)){}var pool=java.util.concurrent.Executors.newSingleThreadExecutor();try(var lock=s.db.jdbc().getDataSource().getConnection()){lock.setAutoCommit(false);try(var q=lock.prepareStatement("select operation_id from comparison_refresh_receipt where operation_id=? for update")){q.setString(1,s.request.operationId().toString());q.executeQuery().close();}var proof=pool.submit(()->s.uses.proof(s.request.operationId(),"1"));long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(2);boolean waiting=false;while(System.nanoTime()<end){if(s.db.jdbc().queryForObject("select count(*) from performance_schema.data_lock_waits",Integer.class)>0){waiting=true;break;}Thread.sleep(10);}assertTrue(waiting);s.clock.advance(Duration.ofSeconds(91));lock.commit();assertEquals("FAILED",proof.get(4,java.util.concurrent.TimeUnit.SECONDS).path("state").asText());assertEquals("FAILED",s.db.jdbc().queryForObject("select state from comparison_refresh_receipt",String.class));}finally{pool.shutdownNow();}}

 @Test void expirationDuringWindowReadPreventsCollector(){
  var s=new Setup();
  doAnswer(c->{var value=c.callRealMethod();s.clock.advance(Duration.between(s.clock.instant(),s.request.leaseUntil().plusSeconds(1)));return value;}).when(s.query).fixedWindow(any());
  var done=s.service().refresh(s.request);
  assertEquals(0,s.calls.get());
  assertEquals("FAILED",done.state());
  assertEquals("ATTEMPT_EXPIRED",done.errorCode());
  assertEquals(0,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());
 }

}
